interface.definition:
a!localVariables(
  local!date: now(),
  local!docId: ri!appianDoc,
  local!addedDoc,
  local!files,
  local!loggedInUser: loggedInUser(),
  local!isUserCandidate: isusermemberofgroups(
    user: tostring(local!loggedInUser),
    groups: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3175918"
  ),
  local!isCandidateDoc: or(
    and(
      toboolean(local!isUserCandidate),
      ri!statusId = #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3927661"
    ),
    and(
      isusermemberofgroups(
        user: tostring(local!loggedInUser),
        groups: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3174922"
      ),
      ri!statusId = #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3935295"
    )
  ),
  #"SYSTEM_SYSRULES_cardLayout"(
    showWhen: ri!showWhen,
    marginBelow: "STANDARD",
    contents: {
      #"SYSTEM_SYSRULES_fileUploadField_v1"(
        label: "Attachments" & if(
          and(
            ri!isNomination,
            or(
              ri!isDirectHire = false,
              a!isNullOrEmpty(ri!isDirectHire)
            )
          ),
          " *",
          ""
        ),
        instructions: if(
          ri!isNomination = true,
          "Please upload the candidates resume using the attachment button above",
          "Use this tool to upload any attachments to this form"
        ),
        requiredMessage: "Please upload at least one attachment to submit",
        target: if(
          local!isCandidateDoc,
          #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4644400",
          #"_a-0000e6ca-52ed-8000-9bff-011c48011c48_3699872"
        ),
        value: local!docId,
        saveInto: {
          local!docId,
          a!save(
            local!addedDoc,
            difference(
              tointeger(save!value),
              tointeger(ri!appianDoc)
            )
          ),
          a!save(
            ri!documentsToDelete,
            difference(
              tointeger(ri!appianDoc),
              tointeger(save!value)
            )
          ),
          if(
            #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(ri!document),
            null,
            a!save(
              ri!document,
              remove(
                ri!document,
                wherecontains(
                  difference(
                    tointeger(
                      property(
                        index(
                          ri!document,
                          wherecontains(
                            tointeger(null),
                            tointeger(
                              property(ri!document, "documentId", null)
                            )
                          ),
                          null
                        ),
                        "docId",
                        null
                      )
                    ),
                    tointeger(local!addedDoc)
                  ),
                  tointeger(property(ri!document, "docId", null))
                )
              )
            )
          ),
          a!save(
            ri!document,
            if(
              a!isNullOrEmpty(local!addedDoc),
              ri!document,
              append(
                ri!document,
                #"SYSTEM_SYSRULES_forEach"(
                  items: local!addedDoc,
                  expression: 'type!{urn:com:appian:types:CAW}CAW_Document'(
                    documentId: null,
                    moduleId: ri!moduleId,
                    requestId: ri!requestId,
                    taskId: ri!taskId,
                    docId: tointeger(fv!item),
                    version: ri!version,
                    isActive: true,
                    isLocked: false,
                    createdBy: loggedInUser(),
                    createdOn: local!date,
                    modifiedBy: loggedInUser(),
                    modifiedOn: local!date
                  )
                )
              )
            )
          ),
          if(
            toboolean(local!isCandidateDoc),
            a!save(ri!document.isCandidateDoc, true),
            null
          ),
          a!save(
            ri!document,
            union(ri!document, ri!document)
          )
        },
        validations: a!localVariables(
          local!invalidExtensions: difference(
            touniformstring(fv!files.extension),
            touniformstring(
              {
                "pdf",
                "doc",
                "docx",
                "xls",
                "xlsx",
                "ppt",
                "pptx",
                "csv"
              }
            )
          ),
          if(
            length(local!invalidExtensions) > 0,
            "Attachments must be PDF, DOC, DOCX , XLS, XLSX, PPT, PPTX, CSV files. Remove: " & index(
              fv!files,
              "name",
              wherecontains(
                touniformstring(local!invalidExtensions),
                touniformstring(fv!files.extension)
              ),
              {}
            ),
            ""
          )
        )
      )
    }
  )
)
